'use strict';

// MODULES //

var format = require( '@stdlib/string/format' );
var NAMESPACE_SEGMENTS = require( './namespace_segments.json' );


// VARIABLES //

// Pattern to match `@stdlib/` prefix (which should not be used):
var RE_STDLIB_PREFIX = /@stdlib\//g;

// Pattern to match text inside backticks:
var RE_BACKTICK_CONTENT = /`[^`]+`/g;

// Pattern to match URLs (to exclude from package path detection):
var RE_URL = /(?:https?|ftp):\/\/[^\s]+/g;

/*
* Pattern to match potential stdlib package paths.
*
* Matches paths that:
* -   Start with a known stdlib namespace segment
* -   Have at least 2 segments (e.g., `math/base` or `dists/chi`)
* -   Each segment is lowercase alphanumeric with underscores or hyphens
*
* The namespace segments are loaded from a static JSON file generated from
* `@stdlib/_tools/pkgs/namespaces`. To regenerate:
*
* ```bash
* NODE_PATH=lib/node_modules node -e "
* var ns = require('@stdlib/_tools/pkgs/namespaces').sync();
* var segments = {};
* ns.forEach(function(n) {
*     var parts = n.replace('@stdlib/', '').split('/');
*     parts.forEach(function(p) { if (p.charAt(0) !== '_') segments[p] = true; });
* });
* console.log(JSON.stringify(Object.keys(segments).sort(), null, '  '));
* " > lib/node_modules/@stdlib/_tools/commitlint/rules/package-reference-format/lib/namespace_segments.json
* ```
*/
var RE_PKG_PATH = new RegExp( '\\b((?:' + NAMESPACE_SEGMENTS.join( '|' ) + ')(?:\\/[a-z][a-z0-9_-]*)+)\\b', 'g' );


// MAIN //

/**
* Rule to enforce stdlib package reference format in commit messages.
*
* ## Notes
*
* -   Package references must be wrapped in backticks.
* -   Package references must NOT include the `@stdlib/` prefix.
*
* @param {Object} parsed - parsed commit
* @param {string} [when='always'] - condition
* @returns {Array} result
*/
function packageReferenceFormat( parsed, when ) {
	var subjectWithoutBackticks;
	var messages;
	var subject;
	var match;
	var valid;
	var msg;

	if ( when === 'never' ) {
		return [ true, '' ];
	}
	messages = [];
	subject = parsed.subject || '';

	// Check for @stdlib/ prefix anywhere in the subject:
	RE_STDLIB_PREFIX.lastIndex = 0;
	if ( RE_STDLIB_PREFIX.test( subject ) ) {
		messages.push( 'Package references must not include the `@stdlib/` prefix. Use `pkg/path` instead of `@stdlib/pkg/path`.' );
	}

	// Remove all backtick-enclosed content to find unquoted package paths:
	subjectWithoutBackticks = subject.replace( RE_BACKTICK_CONTENT, '' );

	// Remove URLs to avoid false positives:
	subjectWithoutBackticks = subjectWithoutBackticks.replace( RE_URL, '' );

	// Check for unquoted package paths starting with known stdlib namespace segments:
	RE_PKG_PATH.lastIndex = 0;
	match = RE_PKG_PATH.exec( subjectWithoutBackticks );
	while ( match !== null ) {
		messages.push( format( 'Package reference `%s` must be wrapped in backticks.', match[ 1 ] ) );
		match = RE_PKG_PATH.exec( subjectWithoutBackticks );
	}

	valid = ( messages.length === 0 );
	msg = messages.join( ' ' );
	return [ valid, msg ];
}


// EXPORTS //

module.exports = packageReferenceFormat;
